use rocket::http::Status;use rocket::response::status;use thiserror::Error;#[derive(Debug,Error)]pub enum ApiError{#[error("Not found")]NotFound,#[error("Bad request: {0}")]BadRequest(String),#[error(transparent)]Sqlx(#[from] sqlx::Error),#[error(transparent)]Anyhow(#[from] anyhow::Error),}impl From<ApiError> for status::Custom<rocket::serde::json::Value>{fn from(e:ApiError)->Self{let (c,m) = match &e {ApiError::NotFound=>(Status::NotFound,e.to_string()),ApiError::BadRequest(_)=>(Status::BadRequest,e.to_string()),_=>(Status::InternalServerError,"Internal server error".into())};status::Custom(c,rocket::serde::json::json!({"error":m}))}}
